SELECT id, user_id, role, content, created_at
FROM chat_messages
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT id, user_id, role, content, created_at
FROM chat_messages
WHERE user_id = #{userId}
  AND created_at >= #{from}
  AND created_at < #{to}
ORDER BY created_at ASC, id ASC
